class Point {
public:
  // Logically const function can be called on const objects
  double distanceFromOrigin() const noexcept
  {
    // Atomic increment is thread-safe
    ++callCount;
    return 0.0; // Simplified for example
  }

  unsigned getCallCount() const { return callCount.load(); }

private:
  // Mutable allows modification inside a const member function
  mutable std::atomic<unsigned> callCount{ 0 };
  double x{0.0}, y{0.0};
};
